const readDemoVipMinimums=()=>{
  try{
    const raw=localStorage.getItem('territory_crm_demo_state');
    const venue=raw?JSON.parse(raw)?.venue:null;
    const configured=venue?.vipRoomMinimums||{};
    return {
      'vip-room-1':Number(configured['vip-room-1']??configured.vipRoom1??1500),
      'vip-room-2':Number(configured['vip-room-2']??configured.vipRoom2??2500)
    };
  }catch(_){return {'vip-room-1':1500,'vip-room-2':2500};}
};
const tableMinimums=readDemoVipMinimums();
const orderHeaders=()=>({...sessionHeaders(),'Content-Type':'application/json'});
const staticStaffDemo=()=>String(localStorage.getItem('crm_session_token')||'').startsWith('demo-static-');
const localOrders=()=>{try{return JSON.parse(localStorage.getItem('territory_crm_staff_orders')||'[]');}catch(_){return[];}};
const saveLocalOrders=(items)=>localStorage.setItem('territory_crm_staff_orders',JSON.stringify(items));
const staticOrderApi=async(url,options={})=>{const path=new URL(url,location.origin).pathname;const method=options.method||'GET';const input=options.body?JSON.parse(options.body):{};let list=localOrders();const orderEdit=path.match(/^\/api\/orders\/([^/]+)$/);if(orderEdit&&method==='PATCH'){const order=list.find(x=>x.id===orderEdit[1]);if(!order)throw new Error('HTTP 404');if(input.notes!==undefined)order.notes=String(input.notes||'');if(input.guestName!==undefined||input.phone!==undefined){order.guestName=String(input.guestName||'').trim();order.guestPhone=String(input.phone||'').trim();}saveLocalOrders(list);return {...order,guestName:order.guestName,phone:order.guestPhone};}if(path==='/api/orders'&&method==='GET')return{items:list};if(path==='/api/orders'&&method==='POST'){const order={id:`local-order-${Date.now()}`,tableId:input.tableId||'table-8',minimumOrderTotal:Number(input.minimumOrderTotal||0),status:'open',items:[]};list.push(order);saveLocalOrders(list);return order;}const item=path.match(/^\/api\/orders\/([^/]+)\/items(?:\/([^/]+))?$/);if(item&&method==='POST'){const order=list.find(x=>x.id===item[1]);const product=products.find(x=>x[4]===input.productId||x[0]===input.productId);const added={id:`local-item-${Date.now()}`,productId:input.productId,name:product?.[0]||input.productId,quantity:Number(input.quantity||1),unitPrice:Number(product?.[1]||0)};if(order)order.items.push(added);saveLocalOrders(list);return added;}if(item&&(method==='PATCH'||method==='DELETE')){const order=list.find(x=>x.id===item[1]);const entry=order?.items?.find(x=>x.id===item[2]);if(!entry)throw new Error('HTTP 404');if(method==='DELETE'){order.items=order.items.filter(x=>x.id!==entry.id);saveLocalOrders(list);return{id:entry.id};}entry.quantity=Number(input.quantity);saveLocalOrders(list);return entry;}const action=path.match(/^\/api\/orders\/([^/]+)\/(status|transfer|close|payments|discount-requests)$/);if(action){const order=list.find(x=>x.id===action[1]);if(!order)throw new Error('HTTP 404');if(action[2]==='status')order.status=input.status;if(action[2]==='transfer')order.tableId=input.tableId;if(action[2]==='close'){order.status='closed';const subtotal=(order.items||[]).reduce((s,x)=>s+x.unitPrice*x.quantity,0);order.subtotal=subtotal;order.finalTotal=Math.max(subtotal,Number(order.minimumOrderTotal||0));order.minimumAdjustment=Math.max(0,Number(order.minimumOrderTotal||0)-subtotal);order.paymentMethod=input.paymentMethod||'cash';}if(action[2]==='payments'){order.payments ||= [];const subtotal=(order.items||[]).reduce((s,x)=>s+x.unitPrice*x.quantity,0);const due=Math.max(subtotal,Number(order.minimumOrderTotal||0));const paid=order.payments.reduce((sum,x)=>sum+Number(x.amount),0);if(method==='GET')return{items:order.payments,due,paid,remaining:Math.max(0,due-paid)};const amount=Number(input.amount);if(!['cash','card','qr'].includes(String(input.method||'cash'))||!Number.isFinite(amount)||amount<=0||paid+amount>due+0.01)throw new Error('HTTP 409');const payment={id:`local-pay-${Date.now()}`,method:input.method||'cash',amount,status:'paid',createdAt:new Date().toISOString()};order.payments.push(payment);const nextPaid=paid+amount;if(nextPaid>=due)order.status='closed';saveLocalOrders(list);return{...payment,due,paid:nextPaid,remaining:Math.max(0,due-nextPaid),closed:nextPaid>=due};}saveLocalOrders(list);return order;}return{};};
const staticSplitApi=async(url,options={})=>{const path=new URL(url,location.origin).pathname;const match=path.match(/^\/api\/orders\/([^/]+)\/split$/);if(!match)return null;const input=options.body?JSON.parse(options.body):{};const list=localOrders();const source=list.find((x)=>x.id===match[1]);if(!source)throw new Error('HTTP 404');const ids=new Set(input.itemIds||[]);const moved=(source.items||[]).filter((x)=>ids.has(x.id));if(!moved.length)throw new Error('HTTP 400');source.items=(source.items||[]).filter((x)=>!ids.has(x.id));const target={id:`local-order-${Date.now()}`,tableId:source.tableId,status:'open',minimumOrderTotal:source.minimumOrderTotal||0,items:moved,splitFrom:source.id};list.push(target);saveLocalOrders(list);return target;};
const apiJson=(url,options={})=>staticStaffDemo()?(url.endsWith('/split')?staticSplitApi(url,options):staticOrderApi(url,options)):fetch(url,{...options,headers:{...sessionHeaders(),...(options.headers||{})}}).then(r=>r.ok?r.json():Promise.reject(new Error(`HTTP ${r.status}`)));
let currentShift=null;
const shiftApi=(options={})=>{if(staticStaffDemo()){let saved;try{saved=JSON.parse(localStorage.getItem('territory_crm_shift')||'null');}catch(_){saved=null;}if(!options.method)return Promise.resolve({items:saved?[saved]:[],current:saved});if(options.method==='POST'&&options.url?.endsWith('/close')){if(saved){saved.closedAt=new Date().toISOString();saved.closingCash=Number(JSON.parse(options.body||'{}').closingCash||0);localStorage.setItem('territory_crm_shift',JSON.stringify(saved));}return Promise.resolve(saved);}const input=options.body?JSON.parse(options.body):{};saved={id:`local-shift-${Date.now()}`,openedAt:new Date().toISOString(),closedAt:null,openingCash:Number(input.openingCash||0)};localStorage.setItem('territory_crm_shift',JSON.stringify(saved));return Promise.resolve(saved);}return fetch(options.url||'/api/shifts',{...options,headers:{...sessionHeaders(),...(options.headers||{})}}).then(r=>r.ok?r.json():Promise.reject(new Error(`HTTP ${r.status}`)));};
const refreshShift=()=>shiftApi().then((result)=>{currentShift=result.current||null;const button=document.querySelector('#shift-toggle');if(button)button.textContent=currentShift?'● Смена открыта':'○ Открыть смену';}).catch(()=>{});
