const orderRows=document.querySelector('.items');
function drawOrder(order){
  currentOrder=order||null;
  const title=document.querySelector('.order h2');
  const tableLabel=order?.tableId ? ({'vip-room-1':'VIP-комната 1','vip-room-2':'VIP-комната 2'}[String(order.tableId)]||`Стол ${String(order.tableId).replace(/^table-/,'')}`) : 'Стол 8';
  if(title) title.textContent=tableLabel;
  if(!orderRows)return;
  const items=order?.items||[];
  orderRows.innerHTML=items.length?items.map(item=>`<div class="order-item-row" data-item-id="${item.id}"><span>${item.name||item.productName||'Позиция'}</span><span class="quantity-control"><button class="qty-minus" data-item="${item.id}" aria-label="Уменьшить">−</button><b>${item.quantity||1}</b><button class="qty-plus" data-item="${item.id}" aria-label="Увеличить">＋</button></span><b>${Number(item.unitPrice||item.price||0)*(item.quantity||1)} ₽</b></div>`).join(''):'<div class="empty-order">Позиции пока не добавлены</div>';
  const meta=document.querySelector('.meta'); if(meta) meta.textContent=`👥 ${order?.guests||2} гостя${order?.guestName?` · ${order.guestName}`:''}  ·  ⏱ обслуживание`;
  recalc();
}
let queueFilter='all';
function drawQueue(filter=queueFilter){queueFilter=filter;const chips=document.querySelectorAll('.chips span');if(chips.length<4)return;const all=openOrders.filter((order)=>order.status!=='closed'&&order.status!=='cancelled').length;const fresh=openOrders.filter((order)=>order.status==='open').length;const cooking=openOrders.filter((order)=>order.status==='in_progress').length;const ready=openOrders.filter((order)=>order.status==='ready').length;[all,fresh,cooking,ready].forEach((value,index)=>{const labels=['Все','Новый заказ','Готовится','Готово'];chips[index].textContent=`${labels[index]} ${value}`;chips[index].classList.toggle('active',chips[index].dataset.filter===queueFilter);});const list=document.querySelector('#queue-list');if(!list)return;const visible=openOrders.filter((order)=>{if(order.status==='closed'||order.status==='cancelled')return false;return queueFilter==='all'||order.status===queueFilter;});list.innerHTML=visible.length?visible.map((order)=>{const label=order.status==='ready'?'Готово':order.status==='in_progress'?'Готовится':'Новый заказ';const table=String(order.tableId||'').replace(/^table-/,'');const total=(order.items||[]).reduce((sum,item)=>sum+Number(item.unitPrice||item.price||0)*Number(item.quantity||1),0);return `<button class="queue-card" data-queue-table="${order.tableId||''}"><span><b>Стол ${table||'—'}</b><small>${(order.items||[]).length} поз. · ${total.toLocaleString('ru-RU')} ₽</small></span><em>${label}</em></button>`;}).join(''):'<div class="queue-empty">В этом разделе пока нет заказов</div>';}

function loadOrders(){return apiJson('/api/orders').then(payload=>{openOrders=payload.items||[]; drawQueue(); const selected=openOrders.find(o=>String(o.tableId)==='table-8'||String(o.tableId)==='8'); drawOrder(selected||{tableId:'table-8',items:[]});}).catch(()=>{openOrders=[];drawQueue();drawOrder({tableId:'table-8',items:[]});});}
loadOrders();
const renderZone=(zone)=>{const serverTables=zone?.tables||[]; if(!serverTables.length)return; serverTables.forEach((t)=>{tableMinimums[t.id]=Number(t.minimumOrderTotal||0);}); tables.innerHTML=serverTables.map(t=>{const label=t.status==='occupied'?'Занят':t.status==='reserved'?'Бронь':'Свободен'; return `<button class="table ${t.status==='occupied'?'busy':t.status==='reserved'?'reserve':'free'} ${t.name==='Стол 8'?'sel':''}" data-table="${t.id}"><strong>${t.name.replace(/^Стол /,'')}</strong><em>${label}</em><small>${t.capacity||'2–4'} гостя</small></button>`}).join('');};
fetch('/api/floor',{headers:sessionHeaders()}).then(r=>r.ok?r.json():null).then(payload=>{serverZones=payload?.zones||[]; renderZone(serverZones[0]);}).catch(()=>{});
if(operatorMode) notice('Открыт временный режим рабочего места. Действия записываются за вашей учётной записью.');
tables.addEventListener('click',event=>{const card=event.target.closest('.table'); if(!card)return; document.querySelectorAll('.table').forEach(x=>x.classList.remove('sel')); card.classList.add('sel'); const id=String(card.dataset.table).startsWith('table-')?card.dataset.table:`table-${card.dataset.table}`; const found=openOrders.find(o=>String(o.tableId)===id||String(o.tableId)===String(card.dataset.table)); if(found)drawOrder(found); else { currentOrder=null; document.querySelector('.order h2').textContent='Стол '+card.dataset.table; drawOrder({tableId:id,items:[]}); }});
const catalog=document.querySelector('#catalog'), grid=document.querySelector('#catalog-grid'), search=document.querySelector('#product-search');
let products=[['Кальян — Darkside Blueberry',1200,['кальян','darkside','blueberry'],null],['Лимонад Маракуйя',300,['лимонад','маракуйя','maracuya'],null],['Red Bull',250,['red bull','ред булл','энергетик'],null],['Чай Эрл Грей',300,['чай','earl grey'],null],['Чаша глиняная',500,['чаша'],null],['Уголь Coco Nara',600,['уголь','coco nara'],null]];
function draw(q=''){grid.innerHTML=products.filter(([name,,aliases=[]])=>[name,...aliases].join(' ').toLowerCase().includes(q.toLowerCase())).map(([name,price,aliases=[],imageUrl])=>{const id=products.find(x=>x[0]===name)?.[4]||name.toLowerCase().replace(/[^a-z0-9]+/g,'-'); return `<button class="product" data-id="${id}" data-name="${name}" data-price="${price}">${imageUrl?`<img src="${imageUrl}" alt="">`:'<span class="product-placeholder">＋</span>'}<span>${name}</span><b>${price} ₽ &nbsp;＋</b></button>`;}).join('');}
draw(); fetch('/api/products',{headers:sessionHeaders()}).then(r=>r.ok?r.json():null).then(data=>{if(data?.items?.length){products=data.items.map(x=>[x.name,x.price,x.aliases||[],x.imageUrl||null,x.id]);draw(search?.value||'');}}).catch(()=>{}); document.querySelector('.primary')?.addEventListener('click',()=>catalog.classList.add('open')); document.querySelector('#catalog-close')?.addEventListener('click',()=>catalog.classList.remove('open')); search?.addEventListener('input',e=>draw(e.target.value));
function recalc(){const total=[...document.querySelectorAll('.items b')].reduce((s,x)=>s+Number(x.textContent.replace(/[^0-9]/g,'')),0); const el=document.querySelector('#order-total'); if(el)el.textContent=total.toLocaleString('ru-RU')+' ₽';}
grid.addEventListener('click',e=>{const item=e.target.closest('.product'); if(!item)return; const add=order=>apiJson(`/api/orders/${order.id}/items`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({productId:item.dataset.id||item.dataset.name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),quantity:1})}); const finish=order=>add(order).then(created=>{order.items=[...(order.items||[]),{...created,name:created.name||item.dataset.name,unitPrice:Number(item.dataset.price)}]; drawOrder(order); catalog.classList.remove('open');}).catch(()=>{const row=document.createElement('div'); row.innerHTML=`${item.dataset.name} <b>${item.dataset.price} ₽</b>`; orderRows.append(row); recalc(); catalog.classList.remove('open');}); if(currentOrder?.id) finish(currentOrder); else {const tableId=document.querySelector('.table.sel')?.dataset.table||'8'; apiJson('/api/orders',{method:'POST',headers:orderHeaders(),body:JSON.stringify({tableId:String(tableId).startsWith('table-')?tableId:`table-${tableId}`,minimumOrderTotal:tableMinimums[tableId]||0})}).then(order=>{openOrders.push(order);finish(order);}).catch(()=>finish({id:'local-order',tableId,minimumOrderTotal:tableMinimums[tableId]||0,items:[]})); }});
orderRows.addEventListener('click',(event)=>{const button=event.target.closest('[data-item]');if(!button||!currentOrder)return;const item=currentOrder.items.find((entry)=>entry.id===button.dataset.item);if(!item)return;const next=Number(item.quantity||1)+(button.classList.contains('qty-plus')?1:-1);if(next<1){apiJson(`/api/orders/${currentOrder.id}/items/${item.id}`,{method:'DELETE',headers:orderHeaders()}).then(()=>{currentOrder.items=currentOrder.items.filter((entry)=>entry.id!==item.id);drawOrder(currentOrder);}).catch(()=>notice('Не удалось удалить позицию'));return;}apiJson(`/api/orders/${currentOrder.id}/items/${item.id}`,{method:'PATCH',headers:orderHeaders(),body:JSON.stringify({quantity:next})}).then(()=>{item.quantity=next;drawOrder(currentOrder);}).catch(()=>notice('Не удалось изменить количество'));});
document.querySelector('.close')?.addEventListener('click',()=>{if(!currentOrder?.id){alert('Сначала добавьте позицию в заказ');return;} const method=window.prompt('Способ оплаты: cash, card или qr','cash')||'cash'; apiJson(`/api/orders/${currentOrder.id}/close`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({paymentMethod:method})}).then(result=>{const closed=openOrders.find((order)=>order.id===currentOrder.id);if(closed)closed.status='closed';drawQueue();alert(`Заказ закрыт на ${Number(result.finalTotal||0).toLocaleString('ru-RU')} ₽`); currentOrder=null; drawOrder({items:[]});}).catch(()=>alert('Не удалось закрыть заказ'));});
document.querySelector('#discount-request')?.addEventListener('click',()=>{if(!currentOrder?.id){alert('Сначала откройте заказ');return;} const value=Number(window.prompt('Размер скидки, %','10')); if(!Number.isFinite(value)||value<=0||value>100)return; const reason=window.prompt('Причина скидки','Лояльность гостя'); if(!reason)return; apiJson(`/api/orders/${currentOrder.id}/discount-requests`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({type:'percent',value,reason})}).then(()=>alert('Заявка отправлена администратору')).catch(()=>alert('Не удалось отправить заявку'));});

const notice=(text)=>{let el=document.querySelector('#staff-notice');if(!el){el=document.createElement('div');el.id='staff-notice';el.className='staff-notice';document.body.append(el);}el.textContent=text;el.classList.add('show');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('show'),2400);};
document.querySelectorAll('aside nav button').forEach((button)=>button.addEventListener('click',()=>{
  document.querySelectorAll('aside nav button').forEach((item)=>item.classList.remove('active')); button.classList.add('active');
  const label=button.textContent.trim(); if(label.includes('Бронирования')) window.location.href='/reservations'; else if(label.includes('Склад')) window.location.href='/inventory'; else if(label.includes('Финансы')) window.location.href='/finance'; else if(label.includes('Заказы')||label.includes('Задачи')) { drawQueue(label.includes('Задачи')?'ready':'all'); document.querySelector('.queue')?.scrollIntoView({behavior:'smooth'}); notice(label.includes('Задачи')?'Показаны готовые задачи':'Показаны активные заказы'); } else document.querySelector('.tables')?.scrollIntoView({behavior:'smooth'});
}));
document.querySelector('#shift-toggle')?.addEventListener('click',()=>{
  if(currentShift){const value=window.prompt('Фактическая сумма в кассе при закрытии','0');if(value===null)return;shiftApi({url:`/api/shifts/${currentShift.id}/close`,method:'POST',body:JSON.stringify({closingCash:Number(value)})}).then(()=>{currentShift=null;refreshShift();notice('Смена закрыта');}).catch(()=>notice('Не удалось закрыть смену'));return;}
  const value=window.prompt('Остаток в кассе при открытии','0');if(value===null)return;shiftApi({method:'POST',body:JSON.stringify({openingCash:Number(value)})}).then((shift)=>{currentShift=shift;refreshShift();notice('Смена открыта');}).catch(()=>notice('Не удалось открыть смену'));
});
