document.querySelectorAll('.actions button').forEach((button)=>button.addEventListener('click',()=>{
  if(!currentOrder?.id){notice('Сначала добавьте позицию в заказ');return;}
  const status=button.textContent.includes('бар')?'in_progress':'ready';
  apiJson(`/api/orders/${currentOrder.id}/status`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({status})}).then(()=>{currentOrder.status=status;const active=openOrders.find((order)=>order.id===currentOrder.id);if(active)active.status=status;drawQueue();notice(status==='in_progress'?'Заказ отправлен на бар':'Задача отправлена кальянщику');}).catch(()=>notice('Не удалось передать заказ'));
}));
document.querySelector('#transfer-order')?.addEventListener('click',()=>{
  if(!currentOrder?.id){notice('Сначала откройте заказ');return;}
  const table=window.prompt('Номер нового стола','1'); if(!table)return; const tableId=String(table).startsWith('table-')?String(table):`table-${table}`;
  apiJson(`/api/orders/${currentOrder.id}/transfer`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({tableId})}).then(()=>{currentOrder.tableId=tableId;document.querySelector('.order h2').textContent=`Стол ${String(table).replace(/^table-/,'')}`;notice('Заказ передан на новый стол');}).catch(()=>notice('Не удалось передать заказ'));
});
document.querySelector('#split-order')?.addEventListener('click',()=>{
  if(!currentOrder?.id || !(currentOrder.items||[]).length){notice('В заказе нет позиций для разделения');return;}
  const lines=currentOrder.items.map((item,index)=>`${index+1}. ${item.name||'Позиция'} ×${item.quantity||1}`).join('\n');
  const raw=window.prompt(`Выберите позиции для нового заказа (номера через запятую):\n${lines}`,'1'); if(!raw)return;
  const indexes=raw.split(',').map((value)=>Number(value.trim())-1).filter((value)=>Number.isInteger(value)&&value>=0&&value<currentOrder.items.length); const itemIds=indexes.map((index)=>currentOrder.items[index].id); if(!itemIds.length){notice('Позиции не выбраны');return;}
  apiJson(`/api/orders/${currentOrder.id}/split`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({itemIds})}).then((target)=>{currentOrder.items=currentOrder.items.filter((item)=>!itemIds.includes(item.id));openOrders.push(target);drawOrder(currentOrder);notice('Новый заказ создан');}).catch(()=>notice('Не удалось разделить заказ'));
});
document.querySelector('#split-payment')?.addEventListener('click',async()=>{
  if(!currentOrder?.id || !(currentOrder.items||[]).length){notice('Сначала добавьте позиции в заказ');return;}
  const subtotal=(currentOrder.items||[]).reduce((sum,item)=>sum+Number(item.unitPrice||0)*Number(item.quantity||1),0); const due=Math.max(subtotal,Number(currentOrder.minimumOrderTotal||0));
  const amounts=[['cash','Наличные'],['card','Карта'],['qr','QR']]; let allocated=0;
  for(const [method,label] of amounts){
    const remaining=due-allocated; if(remaining<=0.01) break;
    const raw=window.prompt(`${label}: внесите сумму\nОстаток ${remaining.toLocaleString('ru-RU')} ₽`,'0'); if(raw===null)return;
    const amount=Number(raw.replace(',','.')); if(!Number.isFinite(amount)||amount<0||amount>remaining){notice('Проверьте сумму платежа');return;}
    if(amount>0){
      try { const result=await apiJson(`/api/orders/${currentOrder.id}/payments`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({method,amount})}); allocated=Number(result.paid||allocated+amount); }
      catch(_){ notice('Не удалось записать платеж'); return; }
    }
  }
  if(allocated>0)notice(allocated>=due?'Заказ оплачен частями':'Платёж сохранён, остаток '+(due-allocated).toLocaleString('ru-RU')+' ₽');
});
document.querySelectorAll('.order-tabs span').forEach((tab)=>tab.addEventListener('click',()=>{
  if(!currentOrder){notice('Сначала выберите стол');return;}
  if(tab.textContent.trim()==='Гости'){const value=window.prompt('Количество гостей',String(currentOrder.guests||2));const guests=Number(value);if(!Number.isFinite(guests)||guests<1)return;const guestName=window.prompt('Имя гостя',currentOrder.guestName||'');if(guestName===null)return;const phone=window.prompt('Телефон гостя',currentOrder.guestPhone||'');if(phone===null)return;apiJson(`/api/orders/${currentOrder.id}`,{method:'PATCH',headers:orderHeaders(),body:JSON.stringify({guestName,phone})}).then((saved)=>{currentOrder.guests=guests;currentOrder.guestName=saved.guestName||guestName;currentOrder.guestPhone=saved.phone||phone;drawOrder(currentOrder);notice('Гость привязан к заказу');}).catch(()=>notice('Не удалось сохранить гостя'));return;}
  const value=window.prompt('Комментарий к заказу',currentOrder.notes||'');if(value===null)return;apiJson(`/api/orders/${currentOrder.id}`,{method:'PATCH',headers:orderHeaders(),body:JSON.stringify({notes:value})}).then(()=>{currentOrder.notes=value;notice(value?'Заметка сохранена':'Заметка очищена');}).catch(()=>notice('Не удалось сохранить заметку'));
}));
document.querySelectorAll('.chips span').forEach((chip)=>chip.addEventListener('click',()=>{drawQueue(chip.dataset.filter||'all');notice(`Фильтр «${chip.textContent.trim().replace(/\s+\d+$/,'')}» применён`);}));
document.querySelector('#queue-list')?.addEventListener('click',(event)=>{const card=event.target.closest('[data-queue-table]');if(!card)return;const table=document.querySelector(`.table[data-table="${card.dataset.queueTable}"]`);if(table)table.click();document.querySelector('.workspace')?.scrollIntoView({behavior:'smooth',block:'start'});});

